  const cap = Math.max(2, Math.min(10000, parseInt(r.cap, 10) || room.cap)); need(cap >= Object.keys(room.members).length, '지금 인원보다 작게 정할 수 없어요'); if ((room.guests || []).length && cap < roomTotal(room)) room.guests.splice(Math.max(0, cap - Object.keys(room.members).length));
