/* ---------- 바이브챗봇 ---------- */
function botSay(room, text, ment) { return addMsg(room, { from: '', t: 'bot', nm: '바이브챗봇', text: String(text).slice(0, 700), img: '', ment: ment || [] }); }
function botReply(room, text) {
  const b = room.bot; if (!b || !b.on) return;
  const t = String(text).trim(); if (!t.startsWith('/')) return;
  const cmd = t.slice(1).split(/\s+/)[0];
  if (cmd === '명령어' || cmd === '도움말') { if ((b.cmds || []).length) botSay(room, '쓸 수 있는 명령어예요\n' + b.cmds.map(x => '/' + x.c).join('  ')); return; }
  const hit = (b.cmds || []).find(x => x.c === cmd); if (hit) botSay(room, hit.a);
}
